// ===== SIMPLIFIED: Just extract and pass through =====

const webhookData = $('Webhook Trigger').first().json;
const kieUploadData = $json;

const formData = webhookData.body || webhookData;

const productName = formData['Product Name'];
const productDescription = formData['Product Description'];
const email = formData['Email'];
const adType = formData['Ad Type'];
const targetAudience = formData['Target Audience'];
const platform = formData['Platform'];
const videoLength = formData['Video Length (includes problem scene + solution scenes)'];
const productionMode = formData['Production Mode'];
const ugcStyleDetails = formData['UGC Style Details'];
const additionalNotes = formData['Additional Notes'] || '';

const uploadedImageUrl = kieUploadData.data?.downloadUrl || kieUploadData.downloadUrl;
const uploadedFileName = kieUploadData.data?.fileName || kieUploadData.fileName;

if (!uploadedImageUrl) {
  throw new Error('Kie-Upload missing downloadUrl');
}

const videoLengthMap = {
  '16s Problem + Solution': { duration: 16, scenes: 2 },
  '24s Problem + Discovery + Success': { duration: 24, scenes: 3 },
  '32s (Problem + Discovery + Trial + Success)': { duration: 32, scenes: 4 },
  '40s (5 scenes total)': { duration: 40, scenes: 5 },
  '48s (6 scenes total)': { duration: 48, scenes: 6 },
  '56s (7 scenes total)': { duration: 56, scenes: 7 },
  '64s (8 scenes total)': { duration: 64, scenes: 8 }
};

const videoConfig = videoLengthMap[videoLength] || { duration: 24, scenes: 3 };

const platformAspectRatioMap = {
  'TikTok/Reels (9:16)': '9:16',
  'YouTube/Facebook (16:9)': '16:9',
  'Instagram Square (1:1)': '1:1',
  'Stories (9:16)': '9:16'
};

const aspectRatio = platformAspectRatioMap[platform] || '9:16';

const requestId = `req_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;
const videoId = `video_${Date.now()}`;

return {
  requestId,
  videoId,
  timestamp: new Date().toISOString(),
  userEmail: email,
  uploadedImageUrl,
  uploadedFileName,
  productName,
  productDescription,
  adType,
  targetAudience,
  platform,
  aspectRatio,
  videoLength,
  duration: videoConfig.duration,
  totalScenes: videoConfig.scenes,
  productionMode,
  ugcStyleDetails,
  additionalNotes,
  isUGC: adType.includes('UGC'),
  isVFX: adType.includes('VFX'),
  isStoryMode: productionMode.includes('Story Mode')
};

// Parse Gemini response and build Nano Banana payload for grid generation
const geminiResponse = $input.all()[0].json;
let analysis = JSON.parse(geminiResponse.content.parts[0].text.replace(/```json/g, '').replace(/```/g, '').trim());

const kieUploadData = $('Kie-Upload').all()[0].json.data;
const referenceImageUrl = kieUploadData.downloadUrl;

const nanoBananaPayload = {
  model: "nano-banana-pro",
  input: {
    prompt: analysis.nano_banana_prompt,
    image_input: [referenceImageUrl],
    aspect_ratio: "1:1",
    resolution: "2K",
    output_format: "png"
  }
};

return [{
  json: {
    nanoBananaPayload,
    productInfo: analysis.product_analysis,
    gridConfig: analysis.grid_configuration,
    ugcCreatorProfile: analysis.ugc_creator_profile,
    videoProductionMetadata: analysis.video_production_metadata,
    referenceImage: { url: referenceImageUrl },
    fullPrompt: analysis.nano_banana_prompt,
    timestamp: new Date().toISOString(),
    status: 'ready_for_nano_banana'
  }
}];

// Extract Grid Image URL
const seedreamResult = $json;
const resultJson = JSON.parse(seedreamResult.data.resultJson);
const generatedGridUrl = resultJson.resultUrls[0];

const kieItems = $('Kie-Upload').all();
const originalImageUrl = kieItems[0].json.data.downloadUrl;

const payloadItems = $('GridParser').all();
const payloadData = payloadItems[0].json;

return [{
  json: {
    images: {
      original: originalImageUrl,
      generatedGrid: generatedGridUrl
    },
    imageUrls: [originalImageUrl, generatedGridUrl],
    product: payloadData.productInfo,
    ugcCreatorProfile: payloadData.ugcCreatorProfile,
    videoProductionMetadata: payloadData.videoProductionMetadata,
    timestamp: new Date().toISOString(),
    status: 'ready_for_character_generation'
  }
}];

// Parse Character Baseline and build Nano Banana payload
const geminiResponse = $input.first().json;
let rawText = geminiResponse.content?.parts?.[0]?.text || geminiResponse.text;
let cleanedText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
let characterData = JSON.parse(cleanedText);

const aiGenerationPrompt = characterData.aiGenerationPrompt;

const nanoBananaPayload = {
  model: "nano-banana-pro",
  input: {
    prompt: aiGenerationPrompt,
    aspect_ratio: "1:1",
    resolution: "2K",
    output_format: "png"
  }
};

return {
  nanoBananaPayload,
  characterPhysical: characterData.characterPhysical,
  characterPresentation: characterData.characterPresentation,
  aiGenerationPrompt,
  consistencyChecklist: characterData.consistencyChecklistMAST,
  timestamp: new Date().toISOString(),
  status: 'ready_for_character_baseline_image'
};

// Extract Character Image URL
const apiResponse = $input.first().json;
const resultJson = JSON.parse(apiResponse.data.resultJson);
const characterImageUrl = resultJson.resultUrls[0];

const characterPayload = $('CharacterPayload').all()[0].json;

return [{
  json: {
    characterImageUrl,
    characterPhysical: characterPayload.characterPhysical,
    characterPresentation: characterPayload.characterPresentation,
    consistencyChecklist: characterPayload.consistencyChecklist,
    timestamp: new Date().toISOString(),
    status: 'character_image_ready'
  }
}];

// ===== VIDEO REQUIREMENTS CALCULATOR =====
// Calculates how many scenes and images needed based on user's video length request

const gridData = $input.all()[0].json; // From GetImgs
const characterData = $input.all()[1].json; // From GetChar
const formData = $('ParseFormData').first().json;

const totalDuration = formData.duration; // e.g., 24
const totalScenes = formData.totalScenes; // e.g., 3
const sceneDuration = Math.floor(totalDuration / totalScenes); // e.g., 8 seconds per scene

// Scene types based on total scenes
const sceneTypeMap = {
  2: ['problem', 'solution'],
  3: ['problem', 'discovery', 'success'],
  4: ['problem', 'discovery', 'trial', 'success'],
  5: ['problem', 'discovery', 'trial_1', 'trial_2', 'success'],
  6: ['problem', 'discovery', 'trial_1', 'trial_2', 'trial_3', 'success'],
  7: ['problem', 'discovery', 'trial_1', 'trial_2', 'trial_3', 'trial_4', 'success'],
  8: ['problem', 'discovery', 'trial_1', 'trial_2', 'trial_3', 'trial_4', 'trial_5', 'success']
};

const sceneTypes = sceneTypeMap[totalScenes] || ['problem', 'discovery', 'success'];

// Build scene configuration
const sceneConfig = sceneTypes.map((type, index) => {
  let description = '';
  let productVisible = false;

  if (type === 'problem') {
    description = 'Problem scene - character experiencing issue before product';
    productVisible = false;
  } else if (type === 'discovery') {
    description = 'Discovery scene - character finds and reveals product';
    productVisible = true;
  } else if (type.includes('trial')) {
    description = 'Trial scene - character testing/using product';
    productVisible = true;
  } else if (type === 'solution' || type === 'success') {
    description = 'Success scene - character satisfied with product, call-to-action';
    productVisible = true;
  }

  return {
    sceneNumber: index,
    type: type,
    duration: sceneDuration,
    description: description,
    productVisible: productVisible,
    startTime: index * sceneDuration,
    endTime: (index + 1) * sceneDuration
  };
});

const output = {
  // Video Configuration
  videoConfig: {
    totalDuration,
    totalScenes,
    sceneDuration,
    aspectRatio: formData.aspectRatio,
    platform: formData.platform
  },

  // Scene Configuration
  sceneConfig,

  // Resource Requirements
  resourceRequirements: {
    totalImagesNeeded: totalScenes, // 1 image per scene
    totalVideoClipsNeeded: totalScenes, // 1 video clip per scene
    estimatedGenerationTime: totalScenes * 60 // ~60 seconds per scene
  },

  // Product & Character Data (pass through)
  productImages: gridData.images,
  productInfo: gridData.product,
  characterImageUrl: characterData.characterImageUrl,
  characterPhysical: characterData.characterPhysical,
  characterConsistency: characterData.consistencyChecklist,

  // UGC Profile (pass through)
  ugcCreatorProfile: gridData.ugcCreatorProfile,
  videoProductionMetadata: gridData.videoProductionMetadata,

  // Form Data (pass through)
  productName: formData.productName,
  productDescription: formData.productDescription,
  targetAudience: formData.targetAudience,
  ugcStyleDetails: formData.ugcStyleDetails,
  additionalNotes: formData.additionalNotes,

  // Status
  timestamp: new Date().toISOString(),
  status: 'video_requirements_calculated',
  progress: 50
};

console.log('✅ Video Requirements Calculated:');
console.log('   Total Duration:', totalDuration, 'seconds');
console.log('   Total Scenes:', totalScenes);
console.log('   Duration per Scene:', sceneDuration, 'seconds');
console.log('   Scene Types:', sceneTypes.join(', '));
console.log('   Images Needed:', totalScenes);

return [{ json: output }];

